<?php
declare(strict_types=1);
class RfidAttendance {
    public function __construct(private mysqli $db) {}
    private function uid(string $uid): string { $uid=strtoupper(trim($uid)); $uid=preg_replace('/[^A-Z0-9]/','',$uid) ?? ''; if($uid===''||strlen($uid)>64) throw new InvalidArgumentException('Invalid RFID UID.'); return $uid; }
    private function uuid(): string { $d=random_bytes(16); $d[6]=chr((ord($d[6])&0x0f)|0x40); $d[8]=chr((ord($d[8])&0x3f)|0x80); return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4)); }
    private function employeeByUid(string $uid): ?array { $s=$this->db->prepare("SELECT e.id,e.employee_code,e.name,e.department,e.designation,e.status,c.id card_id,c.status card_status FROM rfid_cards c JOIN employees e ON e.id=c.employee_id WHERE c.uid=? LIMIT 1"); $s->bind_param('s',$uid); $s->execute(); return $s->get_result()->fetch_assoc() ?: null; }
    private function deviceId(?string $code): ?int { if(!$code) return null; $s=$this->db->prepare('SELECT id FROM attendance_devices WHERE device_code=? AND status="active"'); $s->bind_param('s',$code); $s->execute(); $r=$s->get_result()->fetch_assoc(); return $r ? (int)$r['id'] : null; }
    private function duplicateWindow(): int { $r=$this->db->query("SELECT setting_value FROM attendance_settings WHERE setting_key='duplicate_window_seconds'")->fetch_assoc(); return max(1,min(60,(int)($r['setting_value']??8))); }
    public function registerCard(int $employeeId,string $uid,string $type='MIFARE'): bool { $uid=$this->uid($uid); if($employeeId<1) throw new InvalidArgumentException('Invalid employee.'); $this->db->begin_transaction(); try { $s=$this->db->prepare('SELECT id FROM employees WHERE id=? AND status="active"'); $s->bind_param('i',$employeeId); $s->execute(); if(!$s->get_result()->fetch_assoc()) throw new InvalidArgumentException('Active employee not found.'); $s=$this->db->prepare('SELECT id FROM rfid_cards WHERE uid=? AND status="active"'); $s->bind_param('s',$uid); $s->execute(); if($s->get_result()->fetch_assoc()) throw new InvalidArgumentException('This RFID card is already assigned.'); $s=$this->db->prepare('UPDATE rfid_cards SET status="blocked",updated_at=NOW() WHERE employee_id=? AND status="active"'); $s->bind_param('i',$employeeId); $s->execute(); $s=$this->db->prepare('INSERT INTO rfid_cards(employee_id,uid,card_type,status) VALUES(?,?,?,"active")'); $s->bind_param('iss',$employeeId,$uid,$type); $ok=$s->execute(); $this->db->commit(); return $ok; } catch(Throwable $e){$this->db->rollback(); throw $e;}}
    public function cards(): array { return $this->db->query('SELECT c.*,e.employee_code,e.name,e.department FROM rfid_cards c JOIN employees e ON e.id=c.employee_id ORDER BY c.id DESC')->fetch_all(MYSQLI_ASSOC); }
    public function punch(string $uid, ?string $deviceCode=null, ?string $eventId=null, ?string $punchedAt=null): array {
        $uid=$this->uid($uid); $eventId=$eventId && preg_match('/^[0-9a-fA-F-]{36}$/',$eventId)?$eventId:$this->uuid(); $punchedAt=$punchedAt ?: date('Y-m-d H:i:s'); $dt=DateTime::createFromFormat('Y-m-d H:i:s',$punchedAt); if(!$dt) throw new InvalidArgumentException('Invalid punch timestamp.');
        $this->db->begin_transaction();
        try {
            $existing=$this->db->prepare('SELECT punch_type,employee_id,reason FROM attendance_punches WHERE event_id=?'); $existing->bind_param('s',$eventId); $existing->execute(); if($row=$existing->get_result()->fetch_assoc()){ $this->db->commit(); return ['success'=>true,'duplicate_event'=>true,'punch_type'=>$row['punch_type'],'message'=>'Event already processed.']; }
            $employee=$this->employeeByUid($uid); $deviceId=$this->deviceId($deviceCode);
            if(!$employee || $employee['status']!=='active' || $employee['card_status']!=='active') { $type='REJECTED'; $reason='RFID card is not registered or active.'; $s=$this->db->prepare("INSERT INTO attendance_punches(event_id,employee_id,card_uid,device_id,punch_type,punched_at,sync_status,reason) VALUES(?,?,?,?,?,?, 'rejected', ?)"); $nullEmployee=null; $s->bind_param('sisssss',$eventId,$nullEmployee,$uid,$deviceId,$type,$punchedAt,$reason); $s->execute(); $this->db->commit(); return ['success'=>false,'punch_type'=>'REJECTED','message'=>$reason,'event_id'=>$eventId,'timestamp'=>$punchedAt]; }
            $employeeId=(int)$employee['id']; $window=$this->duplicateWindow(); $s=$this->db->prepare('SELECT punch_type,punched_at FROM attendance_punches WHERE employee_id=? AND punch_type IN ("IN","OUT") AND punched_at>=DATE_SUB(?,INTERVAL ? SECOND) ORDER BY id DESC LIMIT 1'); $s->bind_param('isi',$employeeId,$punchedAt,$window); $s->execute(); if($last=$s->get_result()->fetch_assoc()){ $type='DUPLICATE'; $reason='Repeated card tap within duplicate window.'; $s=$this->db->prepare('INSERT INTO attendance_punches(event_id,employee_id,card_uid,device_id,punch_type,punched_at,reason) VALUES(?,?,?,?,?,?,?)'); $s->bind_param('sisssss',$eventId,$employeeId,$uid,$deviceId,$type,$punchedAt,$reason); $s->execute(); $this->db->commit(); return ['success'=>true,'employee'=>$employee,'punch_type'=>'DUPLICATE','message'=>'Duplicate tap ignored.','timestamp'=>$punchedAt]; }
            $date=substr($punchedAt,0,10); $s=$this->db->prepare('SELECT id,entry_time,exit_time FROM attendance WHERE employee_id=? AND attendance_date=? FOR UPDATE'); $s->bind_param('is',$employeeId,$date); $s->execute(); $att=$s->get_result()->fetch_assoc(); $type=(!$att || empty($att['entry_time']))?'IN':'OUT'; if($type==='OUT' && !empty($att['exit_time'])){$type='DUPLICATE';$reason='Attendance already has an OUT punch.';}
            if($type==='IN') { $time=substr($punchedAt,11,8); $status='present'; $shift='09:00:00'; $setting=$this->db->query("SELECT setting_value FROM attendance_settings WHERE setting_key='shift_start'")->fetch_assoc(); if($setting)$shift=$setting['setting_value']; if($time>$shift){$lateAfter=(int)($this->db->query("SELECT setting_value FROM attendance_settings WHERE setting_key='late_after_minutes'")->fetch_assoc()['setting_value']??10); $start=new DateTime($date.' '.$shift); $actual=new DateTime($punchedAt); if(($actual->getTimestamp()-$start->getTimestamp())>($lateAfter*60))$status='late';} if($att){$s=$this->db->prepare('UPDATE attendance SET status=?,entry_time=? WHERE id=?');$s->bind_param('ssi',$status,$time,$att['id']);$s->execute();}else{$s=$this->db->prepare('INSERT INTO attendance(employee_id,attendance_date,status,entry_time) VALUES(?,?,?,?)');$s->bind_param('isss',$employeeId,$date,$status,$time);$s->execute();}}
            elseif($type==='OUT') { $time=substr($punchedAt,11,8); $s=$this->db->prepare('UPDATE attendance SET exit_time=? WHERE employee_id=? AND attendance_date=?');$s->bind_param('sis',$time,$employeeId,$date);$s->execute(); }
            else {$reason='OUT punch already exists.';}
            $reason=$reason??null; $s=$this->db->prepare('INSERT INTO attendance_punches(event_id,employee_id,card_uid,device_id,punch_type,punched_at,reason) VALUES(?,?,?,?,?,?,?)'); $s->bind_param('sisssss',$eventId,$employeeId,$uid,$deviceId,$type,$punchedAt,$reason); $s->execute(); if($deviceCode){$s=$this->db->prepare('INSERT INTO attendance_devices(device_code,device_name,status,last_seen_at) VALUES(?,?,"active",NOW()) ON DUPLICATE KEY UPDATE last_seen_at=NOW(),status="active"');$name=$deviceCode;$s->bind_param('ss',$deviceCode,$name);$s->execute();}
            $this->db->commit(); return ['success'=>true,'employee'=>$employee,'punch_type'=>$type,'message'=>$type==='IN'?'Check-in recorded':'Check-out recorded','timestamp'=>$punchedAt,'event_id'=>$eventId];
        } catch(Throwable $e){$this->db->rollback();throw $e;}
    }
    public function live(int $limit=30): array { $limit=max(1,min(100,$limit)); $q=$this->db->query('SELECT p.id,p.event_id,p.punch_type,p.punched_at,e.employee_code,e.name,e.department FROM attendance_punches p JOIN employees e ON e.id=p.employee_id ORDER BY p.id DESC LIMIT '.$limit); return $q->fetch_all(MYSQLI_ASSOC); }
    public function todayStats(): array { $today=date('Y-m-d'); $r=$this->db->query("SELECT COUNT(*) total FROM employees WHERE status='active'")->fetch_assoc(); $s=$this->db->prepare("SELECT COUNT(*) c FROM attendance WHERE attendance_date=? AND status IN ('present','late','half_day')");$s->bind_param('s',$today);$s->execute();$p=(int)$s->get_result()->fetch_assoc()['c']; return ['total_active'=>(int)$r['total'],'present'=>$p,'absent'=>max(0,(int)$r['total']-$p)]; }
}
